import{_ as t,o,c as r,a2 as a}from"./chunks/framework.BWuWLRhz.js";const p=JSON.parse('{"title":"使用者手冊","description":"","frontmatter":{},"headers":[],"relativePath":"zh-TW/user-guide/index.md","filePath":"zh-TW/user-guide/index.md","lastUpdated":1787586465000}'),s={name:"zh-TW/user-guide/index.md"};function l(i,e,n,d,c,h){return o(),r("div",null,[...e[0]||(e[0]=[a('<h1 id="使用者手冊" tabindex="-1">使用者手冊 <a class="header-anchor" href="#使用者手冊" aria-label="Permalink to &quot;使用者手冊&quot;">​</a></h1><p>歡迎查閱 Lertaro 官方使用者手冊！Lertaro 是一款為 Windows 深度自訂的極速檔案檢索與生產力啟動器。透過在背景維護高效的記憶體索引樹（NTFS / ReFS 基於底層 USN 變更記錄檔，其他檔案系統基於即時事件監聽），實現千萬級檔案的毫秒級檢索回應。</p><p>本手冊系統化介紹了日常使用所需掌握的各項核心功能與進階特性：</p><ul><li><strong><a href="./getting-started.html">快速上手</a></strong> —— 安裝與便攜版使用、App 與 Service 架構職責、三種視窗形態（快速視窗 / 主視窗 / 內嵌視窗）及基礎操作。</li><li><strong><a href="./search-syntax.html">搜尋語法</a></strong> —— 智慧模糊比對、修飾符（<code>!</code> 排除、<code>&#39;</code> 精確、<code>^</code> 前綴、<code>$</code> 後綴、<code>|</code> 或條件）、磁碟機定向、路徑模式與拼音別名比對。</li><li><strong><a href="./hotkeys.html">快速鍵與互動手勢</a></strong> —— 全域快速鍵速查表、搜尋框 Logo 滑鼠拖曳與重設手勢、滑鼠快速導覽階層式功能表與核心固定按鍵。</li><li><strong><a href="./actions-and-preview.html">動作功能表與即時預覽</a></strong> —— 結果快顯動作面板（<code>Ctrl+O</code>）、主視窗結果互動、內建 QuickLook 音訊影片/文件預覽與外掛模組富文字卡片。</li><li><strong><a href="./space-analyzer.html">空間分析</a></strong> —— 零磁碟 I/O 的極速 Treemap 矩形樹狀圖與體積降序清單，輕鬆發現大檔案。</li><li><strong><a href="./instant-answers.html">即時解答與關鍵字功能</a></strong> —— 始終生效的計算機、環境變數與執行命令，以及處理程序管理（<code>ps</code>）、視窗切換（<code>win</code>）、瀏覽器資料（<code>bm</code>）、設定直達（<code>set</code>）等關鍵字外掛模組。</li><li><strong><a href="./cli.html">命令列搜尋（lff）</a></strong> —— 終端機環境下的互動式模糊尋找伴侶工具，共用記憶體索引，支援管道傳參與 Shell 指令碼聯動。</li><li><strong><a href="./uri-protocol.html">URI 通訊協定（lertaro://）</a></strong> —— 外部超連結、捷徑與指令碼直達搜尋、設定分區及 LocalSend 傳輸。</li><li><strong><a href="./file-manager-support.html">支援的檔案管理器</a></strong> —— Windows 原生檔案對話方塊、Directory Opus、Total Commander、XYplorer、Files 等工具的內嵌與快速導覽整合。</li><li><strong><a href="./settings/">設定項參考</a></strong> —— 執行狀態、索引管理、一般選項、外觀主題、快速鍵綁定、外掛模組設定等各項設定詳細說明。</li><li><strong><a href="./troubleshooting.html">疑難排解</a></strong> —— 全域快速鍵失靈、索引未更新、輸入法候選字浮動視窗及記錄檢視排查指南。</li><li><strong><a href="./donate.html">贊助與支持</a></strong> —— 支持 Lertaro 的持續迭代與開放原始碼維護。</li></ul><div class="tip custom-block github-alert"><p class="custom-block-title">TIP</p><p>如果你是初次接觸 Lertaro，推薦從<a href="./getting-started.html"><strong>快速上手</strong></a>開始閱讀。</p></div>',5)])])}const m=t(s,[["render",l]]);export{p as __pageData,m as default};
